      "stride": "ElevationOfPrivilege",
      "title": "One stolen ETL credential gives admin control of every production database",
      "scenario": "An attacker who gets a foothold on the ETL host, a CI runner, or a config store reads the service account credential and inherits full admin rights on all production databases. From there they can create users, grant themselves access, read or destroy any schema, and disable controls. No further privilege escalation is needed because the account is already the highest privilege in the data estate.",
      "component": "Database service account",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "The ETL pipeline runs with a database service account that has full admin rights on every production database, so new tables work without permission changes."
        }
      ],
      "cwe": ["CWE-250", "CWE-269"],
      "plainLanguage": "The ETL job logs in as a database super-admin, so anyone who steals that one password owns all production data.",
      "requirement": {
        "title": "Run ETL with least-privilege, per-database roles",
        "given": "an ETL job that loads data into production databases",
        "when": "it connects to a database",
        "then": "it uses a role scoped to only the schemas and operations it needs (no server-level admin, no user or grant management), with a separate role per database"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "ETL account can read sensitive data from databases outside its scope",
      "scenario": "Because the account has admin rights on every production database, any bug in the ETL (a mis-scoped query, a wrong config value, a wrong source/target mapping) or any operator misuse of the credential can pull data from unrelated systems such as HR, payments or customer records into the data pipeline and its downstream outputs, where a much wider audience can read it.",
      "component": "ETL pipeline to production databases",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "full admin rights on every production database"
        }
      ],
      "cwe": ["CWE-732", "CWE-200"],
      "plainLanguage": "The pipeline can read every database, so a config mistake can copy data it was never meant to touch.",
      "requirement": {
        "title": "Restrict ETL read access to declared sources",
        "given": "an ETL extraction step",
        "when": "it reads from a production database",
        "then": "access is granted only to the explicitly declared source tables, and any read outside that allow-list fails and is alerted on"
      }
    },
    {
      "stride": "Tampering",
      "title": "Admin-level ETL writes can silently alter or drop production tables",
      "scenario": "An attacker with the ETL credential, or a faulty pipeline run, can issue DDL and DML against any production table: dropping tables, rewriting rows used by live applications, or changing constraints. Because the design deliberately avoids permission changes for new tables, nothing stops writes to tables the ETL does not own, so application data can be corrupted without any approval step.",
      "component": "Production databases",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        {
          "quote": "so new tables work without permission changes"
        }
      ],
      "cwe": ["CWE-269", "CWE-284"],
      "plainLanguage": "The job can change or delete any table in production, not just the ones it owns.",
      "requirement": {
        "title": "Separate schema-change rights from data-load rights",
        "given": "the ETL needs new target tables",
        "when": "a table must be created or altered",
        "then": "the change is made by a reviewed migration using a separate restricted role, and the runtime ETL role has write access only to its own target schema"
      }
    },
    {
      "stride": "Repudiation",
      "title": "Shared admin service account makes database actions untraceable to a person",
      "scenario": "All pipeline activity, and any human use of the same credential, appears in database logs as a single admin service account. After a destructive or suspicious query there is no way to tell which job version, which environment or which operator caused it, so an insider can act under cover of the ETL and incident responders cannot scope the damage.",
      "component": "Database service account",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        {
          "quote": "The ETL pipeline runs with a database service account"
        }
      ],
      "cwe": ["CWE-778"],
      "plainLanguage": "Everything happens as one shared admin login, so you cannot tell who did what.",
      "requirement": {
        "title": "Attribute ETL database sessions",
        "given": "an ETL run connecting to a production database",
        "when": "a session is opened",
        "then": "it uses a short-lived credential issued per job run and carries the job id so every statement can be traced back to a specific run and owner"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Long-lived static service account credential can be replayed from anywhere",
      "scenario": "A static service account password that is never rotated and is valid against every production database can be copied from a build log, a developer laptop or a backup and replayed by anyone who can reach the database network. The database cannot distinguish the real pipeline from an impostor presenting the same credential.",
      "component": "ETL credential handling",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "ETL with service account"
        }
      ],
      "cwe": ["CWE-522", "CWE-798"],
      "plainLanguage": "A long-lived shared password can be copied and reused by someone pretending to be the pipeline.",
      "requirement": {
        "title": "Use short-lived, source-restricted database credentials",
        "given": "the ETL authenticates to a production database",
        "when": "it obtains credentials",
        "then": "it uses short-lived credentials from a secret broker or workload identity, restricted to the ETL host network, and no static password is stored in config or CI"
      }
    }
  ]
}
